CREATE TABLE user_profiles (profile_id UUID PRIMARY KEY, auth_user_id UUID NOT NULL UNIQUE, first_name VARCHAR(100), last_name VARCHAR(100), phone VARCHAR(40), avatar_url TEXT, date_of_birth DATE, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_user_profiles_auth_user_id ON user_profiles(auth_user_id);
CREATE TABLE addresses (address_id UUID PRIMARY KEY, profile_id UUID NOT NULL REFERENCES user_profiles(profile_id), address_type VARCHAR(16) NOT NULL, recipient_name VARCHAR(150), line1 VARCHAR(200) NOT NULL, line2 VARCHAR(200), city VARCHAR(100) NOT NULL, state_region VARCHAR(100), postal_code VARCHAR(30) NOT NULL, country_code VARCHAR(2) NOT NULL, phone VARCHAR(40), is_default BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_addresses_profile_id ON addresses(profile_id); CREATE INDEX idx_addresses_profile_default ON addresses(profile_id,is_default);
CREATE TABLE user_preferences (preference_id UUID PRIMARY KEY, profile_id UUID NOT NULL UNIQUE REFERENCES user_profiles(profile_id), language VARCHAR(10), currency VARCHAR(3), marketing_emails BOOLEAN NOT NULL, order_notifications BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
